/**
 * Advance only if we still own the claim (status=active AND claim_token matches).
 * Returns false when ownership was lost (pause/switch mid-send).
 */
export async function advanceEnrollment(
  supabase: Supabase,
  enrollmentId: string,
  claimToken: string,
  currentStepNumber: number,
  steps: CampaignStep[],
  clock: () => Date = () => new Date()
): Promise<boolean> {
  const plan = planAdvanceEnrollment({
    currentStepNumber,
    steps,
    nowMs: clock().getTime(),
    statusCompleted: ENROLLMENT_STATUS.completed,
  });

  const { data, error } = await supabase
    .from(TABLE.campaignEnrollments)
    .update(plan.payload)
    .eq(COL.id, enrollmentId)
    .eq(COL.status, ENROLLMENT_STATUS.active)
    .eq(COL.claimToken, claimToken)
    .select(ENROLLMENT_CLAIM_SELECT);

  if (!ownershipHit(error, data)) {
    // Stryker disable StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral: log-only (no control flow)
    console.warn('advance_ownership_miss', enrollmentId, plan.type, error);
    // Stryker restore StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral
    return false;
  }

  // Stryker disable StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral: log-only (no control flow)
  console.log(
    'campaign_advanced',
    enrollmentId,
    plan.type,
    plan.type === 'advance' ? plan.nextSendAt : undefined
  );
  // Stryker restore StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral
  return true;
}

async function releaseClaim(
  supabase: Supabase,
  enrollmentId: string,
  claimToken: string,
  clock: () => Date,
  opts?: { nextSendAt?: string }
): Promise<void> {
  const nowMs = clock().getTime();
  await supabase
    .from(TABLE.campaignEnrollments)
    .update(
      releaseClaimPayload({
